           background:#1c1e21; color:#fff; padding:10px 16px; border-radius:9px; font-size:14px;
           opacity:0; transition:opacity .2s; pointer-events:none; }
  .toast.show { opacity:1; }
  @media (max-width:480px){ .row{flex-wrap:wrap;} button.primary{width:100%;} }
</style>
</head>
<body>
<header><h1>My Bookmarks</h1></header>
<main>
  <section class="capture">
    <label for="url">Paste a link to save</label>
    <input id="url" type="text" placeholder="https://…" autocomplete="off" />
    <label for="title">Title <span class="hint">(optional — filled in for you if left blank)</span></label>
    <input id="title" type="text" placeholder="e.g. Article about gardening" autocomplete="off" />
    <div class="row">
      <button id="save" class="primary" disabled>Save link</button>
      <span class="hint" id="cap-hint">Enter a link to enable saving.</span>
    </div>
  </section>

  <p class="list-head">Saved links</p>
  <div id="list"></div>
</main>
<div class="toast" id="toast"></div>

<script>
  var items = [];
  var urlEl = document.getElementById('url');
  var titleEl = document.getElementById('title');
  var saveEl = document.getElementById('save');
  var listEl = document.getElementById('list');
  var hintEl = document.getElementById('cap-hint');
  var toastEl = document.getElementById('toast');

  function normalize(u){
    u = u.trim();
    if(!u) return '';
    if(!/^https?:\/\//i.test(u)) u = 'https://' + u;
    return u;
  }
  function hostOf(u){
    try { return new URL(u).hostname.replace(/^www\./,''); } catch(e){ return u; }
  }
  function titleFromUrl(u){
    var h = hostOf(u);
    return h.charAt(0).toUpperCase() + h.slice(1);
  }
  function fmtDate(d){
    return d.toLocaleDateString(undefined,{month:'short',day:'numeric'}) + ' · ' +
           d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});
  }
  function toast(msg){
    toastEl.textContent = msg; toastEl.classList.add('show');
    clearTimeout(toast._t); toast._t = setTimeout(function(){ toastEl.classList.remove('show'); },1800);
  }

  function render(){
    if(items.length === 0){
      listEl.innerHTML = '<div class="empty">No links saved yet. Paste one above to get started.</div>';
      return;
    }
    listEl.innerHTML = '';
    items.forEach(function(it){
      var el = document.createElement('div');
      el.className = 'item';
      el.innerHTML =
        '<div class="fav">🔖</div>' +
        '<div class="body">' +
          '<p class="title"><a href="'+it.url+'" target="_blank" rel="noopener">'+escapeHtml(it.title)+'</a></p>' +
          '<p class="url">'+escapeHtml(it.url)+'</p>' +
          '<p class="meta">Saved '+fmtDate(it.saved)+'</p>' +
        '</div>';
      listEl.appendChild(el);
    });
  }
  function escapeHtml(s){ return s.replace(/[&<>"]/g,function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }

  function refreshButton(){
    var has = urlEl.value.trim().length > 0;
    saveEl.disabled = !has;
    hintEl.textContent = has ? 'Ready to save.' : 'Enter a link to enable saving.';
  }

  function save(){
    var raw = urlEl.value.trim();
    if(!raw) return;
    var url = normalize(raw);
    var title = titleEl.value.trim() || titleFromUrl(url);
    items.unshift({ url:url, title:title, saved:new Date() });
    urlEl.value=''; titleEl.value=''; refreshButton();
    render(); urlEl.focus();
    toast('Saved “'+title+'”');
  }

  urlEl.addEventListener('input', refreshButton);
  urlEl.addEventListener('keydown', function(e){ if(e.key==='Enter'){ e.preventDefault(); titleEl.focus(); }});
  titleEl.addEventListener('keydown', function(e){ if(e.key==='Enter'){ e.preventDefault(); save(); }});
  saveEl.addEventListener('click', save);

  render(); refreshButton();
  document.body.setAttribute('data-harness-ready','true');
</script>
</body>
</html>

