184:  // Supports: bare words (substring), "quoted phrases", #tag, AND/OR/NOT and
185:  // parentheses. Implicit AND between adjacent terms. NOT > AND > OR. A quoted
186:  // token is always a literal, even if it spells an operator.
187:  function tokenize(q){
195:        toks.push({t:'term',kind:'phrase',val:s.toLowerCase()}); continue; }
200:      if(up==='AND'||up==='OR'||up==='NOT') toks.push({t:'op',val:up});
205:  function parse(toks){
208:    function parseOr(){ var node=parseAnd();
209:      while(peek()&&peek().t==='op'&&peek().val==='OR'){ pos++; node={op:'or',l:node,r:parseAnd()}; }
211:    function parseAnd(){ var node=parseNot();
213:        if(p.t==='op'&&p.val==='OR') break;
215:        if(p.t==='op'&&p.val==='AND'){ pos++; node={op:'and',l:node,r:parseNot()}; }
216:        else { node={op:'and',l:node,r:parseNot()}; } // implicit AND
219:    function parseNot(){ if(peek()&&peek().t==='op'&&peek().val==='NOT'){ pos++; return {op:'not',x:parseNot()}; }
